});

// Design-selected verifier for obligations 2, 3, 10 and 13.
// Read-only: never imports or executes subject code, spawns nothing, writes nothing.
import fs from "node:fs";
import path from "node:path";
import { fileURLToPath } from "node:url";
import crypto from "node:crypto";

const root = path.resolve(path.dirname(fileURLToPath(import.meta.url)), "..");
let checks = 0;
let failures = 0;
const cache = new Map();

function check(id, reasons) {
  checks += 1;
  if (reasons.length === 0) {
    console.log(`ok ${id}`);
  } else {
    failures += 1;
    console.log(`not ok ${id} - ${reasons.join("; ")}`);
  }
}

function read(rel) {
  if (cache.has(rel)) return cache.get(rel);
  let text = null;
  try {
    const bytes = fs.readFileSync(path.join(root, rel));
    console.log(`digest ${rel} sha256:${crypto.createHash("sha256").update(bytes).digest("hex")}`);
    text = bytes.toString("utf8");
  } catch {
    text = null;
  }
  cache.set(rel, text);
  return text;
}

function listFiles(relDir) {
  const out = [];
  const walk = (rel) => {
    for (const entry of fs.readdirSync(path.join(root, relDir, rel), { withFileTypes: true })) {
      const child = rel ? `${rel}/${entry.name}` : entry.name;
      if (entry.isDirectory()) walk(child);
      else out.push(child);
    }
  };
  walk("");
  return out.sort();
}

const SURFACES = [
  "specification/project-conformance.md",
  "design/implementation-design.md",
  "package.json",
  "src/hello.mjs",
  "design/test-design.md",
  "test/component/hello.test.mjs",
  "test/uat/hello.uat.test.mjs",
  "test-execution-plan.json",
];

const EXACT_SETS = {
  specification: ["project-conformance.md"],
  design: ["implementation-design.md", "test-design.md"],
  src: ["hello.mjs"],
  test: ["component/hello.test.mjs", "uat/hello.uat.test.mjs"],
  verification: [
    "check-derivation.mjs",
    "check-documents.mjs",
    "check-inventory.mjs",
    "check-package.mjs",
    "check-plan.mjs",
    "check-verifier-structure.mjs",
  ],
};

const ALLOWED_ROOT = new Set([
  ".abiogenesis",
  "semantic-assets",
  "execution-evidence",
  "original-js-sdlc-bootstrap-declaration.txt",
  "package.json",
  "test-execution-plan.json",
  "specification",
  "design",
  "src",
  "test",
  "verification",
]);
const NOT_DESCENDED = new Set([".abiogenesis", "semantic-assets", "execution-evidence"]);
const SUSPECT_ROOT = /\.(m?js|cjs|sh)$|result|ledger|registry|controller|scheduler/i;
const RESULT_NAME = /execution[-_ ]?result/i;
const MACHINERY = ["odd_sdlc", "abiogenesis", "ledger", "registry", "controller", "scheduler", "child_process", "node:net", "node:http"];

// (a) Each governed surface is a non-empty regular file.
for (const rel of SURFACES) {
  const reasons = [];
  try {
    const stat = fs.lstatSync(path.join(root, rel));
    if (!stat.isFile()) reasons.push("not a regular file");
    else if (stat.size === 0) reasons.push("empty file");
    else read(rel);
  } catch {
    reasons.push("missing");
  }
  check(`surface:${rel}`, reasons);
}

// (b) Subject directories hold exactly the designed files.
const listed = {};
for (const [dir, expected] of Object.entries(EXACT_SETS)) {
  const reasons = [];
  try {
    listed[dir] = listFiles(dir);
    const actual = listed[dir];
    const extra = actual.filter((f) => !expected.includes(f));
    const missing = expected.filter((f) => !actual.includes(f));
    if (extra.length) reasons.push(`unexpected ${extra.join(", ")}`);
    if (missing.length) reasons.push(`missing ${missing.join(", ")}`);
  } catch {
    listed[dir] = [];
    reasons.push("directory missing or unreadable");
  }
  check(`exact-set:${dir}`, reasons);
}

// (c) No authored execution-result file in subject directories or at the root.
let rootEntries = [];
try {
  rootEntries = fs.readdirSync(root, { withFileTypes: true });
} catch {
  rootEntries = [];
}
{
  const reasons = [];
  for (const [dir, files] of Object.entries(listed)) {
    for (const f of files) {
      if (RESULT_NAME.test(path.basename(f))) reasons.push(`${dir}/${f}`);
    }
  }
  for (const entry of rootEntries) {
    if (!entry.isDirectory() && RESULT_NAME.test(entry.name)) reasons.push(entry.name);
  }
  check("no-authored-result", reasons.map((r) => `authored result file ${r}`));
}

// (d) Root entries: no node_modules or bin; unknown entries must not look like machinery.
{
  const reasons = [];
  if (rootEntries.length === 0) reasons.push("root unreadable");
  for (const entry of rootEntries) {
    const name = entry.name;
    if (name === "node_modules" || name === "bin") {
      reasons.push(`forbidden root entry ${name}`);
      continue;
    }
    if (ALLOWED_ROOT.has(name) || NOT_DESCENDED.has(name)) continue;
    if (SUSPECT_ROOT.test(name)) reasons.push(`suspect root entry ${name}`);
    else console.log(`note ${name}`);
  }
  check("root-entries", reasons);
}

// (e) No copied machinery in package, source, verifiers or plan. Documents are exempt.
for (const rel of ["package.json", "src/hello.mjs", "test/component/hello.test.mjs", "test/uat/hello.uat.test.mjs", "test-execution-plan.json"]) {
  const reasons = [];
  const text = read(rel);
  if (text === null) {
    reasons.push("missing or unreadable");
  } else {
    if (rel === "src/hello.mjs") {
      if (/\bimport\b/.test(text)) reasons.push("import token");
      if (text.includes("require(")) reasons.push("require( token");
    }
    const lower = text.toLowerCase();
    for (const token of MACHINERY) {
      if (lower.includes(token)) reasons.push(`contains ${token}`);
    }
  }
  check(`no-copied-machinery:${rel}`, reasons);
}

console.log(`check-inventory: ${checks} checks, ${failures} failures`);
if (failures > 0) process.exitCode = 1;

// Design-selected verifier for obligations 1 and 2.
// Read-only: never imports or executes subject code, spawns nothing, writes nothing.
import fs from "node:fs";
import path from "node:path";
import { fileURLToPath } from "node:url";
import crypto from "node:crypto";

const root = path.resolve(path.dirname(fileURLToPath(import.meta.url)), "..");
let checks = 0;
let failures = 0;

function check(id, reasons) {
  checks += 1;
  if (reasons.length === 0) {
    console.log(`ok ${id}`);
  } else {
    failures += 1;
    console.log(`not ok ${id} - ${reasons.join("; ")}`);
  }
}

let text = null;
try {
  const bytes = fs.readFileSync(path.join(root, "package.json"));
  console.log(`digest package.json sha256:${crypto.createHash("sha256").update(bytes).digest("hex")}`);
  text = bytes.toString("utf8");
} catch {
  text = null;
}

let pkg = null;
let parseReason = null;
if (text === null) {
  parseReason = "package.json missing or unreadable";
} else {
  try {
    pkg = JSON.parse(text);
    if (pkg === null || typeof pkg !== "object" || Array.isArray(pkg)) {
      parseReason = "package.json is not a JSON object";
      pkg = null;
    }
  } catch (error) {
    parseReason = `package.json does not parse: ${error.message}`;
  }
}

check("package-parses", parseReason ? [parseReason] : []);
check("private-true", pkg === null ? [parseReason] : pkg.private === true ? [] : [`private is ${JSON.stringify(pkg.private)}`]);
check("type-module", pkg === null ? [parseReason] : pkg.type === "module" ? [] : [`type is ${JSON.stringify(pkg.type)}`]);
{
  const keys = pkg === null ? null : Object.keys(pkg).sort();
  check(
    "keys-exact",
    keys === null ? [parseReason] : JSON.stringify(keys) === JSON.stringify(["private", "type"]) ? [] : [`keys are ${JSON.stringify(keys)}`],
  );
}

console.log(`check-package: ${checks} checks, ${failures} failures`);
if (failures > 0) process.exitCode = 1;

// Design-selected verifier for obligations 4, 5 and 6.
// Proves presence of required document elements, not faithfulness.
// Read-only: never imports or executes subject code, spawns nothing, writes nothing.
import fs from "node:fs";
import path from "node:path";
import { fileURLToPath } from "node:url";
import crypto from "node:crypto";

const root = path.resolve(path.dirname(fileURLToPath(import.meta.url)), "..");
let checks = 0;
let failures = 0;

function check(id, reasons) {
  checks += 1;
  if (reasons.length === 0) {
    console.log(`ok ${id}`);
  } else {
    failures += 1;
    console.log(`not ok ${id} - ${reasons.join("; ")}`);
  }
}

function read(rel) {
  try {
    const bytes = fs.readFileSync(path.join(root, rel));
    console.log(`digest ${rel} sha256:${crypto.createHash("sha256").update(bytes).digest("hex")}`);
    return bytes.toString("utf8");
  } catch {
    return null;
  }
}

// Each needle is [text, exact]; non-exact needles compare case-insensitively.
function missing(text, rel, needles) {
  if (text === null) return [`${rel} missing or unreadable`];
  const lower = text.toLowerCase();
  const reasons = [];
  for (const [needle, exact] of needles) {
    const found = exact ? text.includes(needle) : lower.includes(needle.toLowerCase());
    if (!found) reasons.push(`${rel} lacks '${needle}'`);
  }
  return reasons;
}

const CONFORMANCE = "specification/project-conformance.md";
const IMPLEMENTATION = "design/implementation-design.md";
const TEST_DESIGN = "design/test-design.md";

const conformance = read(CONFORMANCE);
check("conformance-pressure", missing(conformance, CONFORMANCE, [["JavaScript Hello World software build traversal", false]]));
for (const name of [
  "implementation design",
  "source",
  "test design",
  "component test source",
  "UAT test source",
  "test execution plan",
  "test execution result",
]) {
  check(`conformance-surface:${name}`, missing(conformance, CONFORMANCE, [[name, false]]));
}
check(
  "conformance-ownership",
  missing(conformance, CONFORMANCE, [
    ["ABG owns startup admission, registry selection, graph-call opening, vector traversal, F_P dispatch, evidence admission, event emission, closure, and convergence.", true],
  ]),
);
check("conformance-authority-for-design", missing(conformance, CONFORMANCE, [["design/implementation-design.md", false]]));

const implementation = read(IMPLEMENTATION);
check("design-authority", missing(implementation, IMPLEMENTATION, [["Authority: specification/project-conformance.md", true]]));
check("design-module", missing(implementation, IMPLEMENTATION, [["helloWorld", false], ["Hello, world!", true]]));
for (const name of [
  "package.json",
  "src/hello.mjs",
  "design/test-design.md",
  "test/component/hello.test.mjs",
  "test/uat/hello.uat.test.mjs",
  "test-execution-plan.json",
  "execution result",
]) {
  check(`design-surface:${name}`, missing(implementation, IMPLEMENTATION, [[name, false]]));
}
check("design-package-fields", missing(implementation, IMPLEMENTATION, [["private", false], ["module", false]]));

const testDesign = read(TEST_DESIGN);
check("test-design-evidence-source", missing(testDesign, TEST_DESIGN, [["Evidence source: package.json and src/hello.mjs", true]]));
check(
  "test-design-component",
  missing(testDesign, TEST_DESIGN, [["test/component/hello.test.mjs", false], ["helloWorld", false], ["Hello, world!", true]]),
);
check("test-design-uat", missing(testDesign, TEST_DESIGN, [["test/uat/hello.uat.test.mjs", false], ["same exported function", false]]));
check("test-design-libraries", missing(testDesign, TEST_DESIGN, [["node:test", false], ["node:assert/strict", false]]));

console.log(`check-documents: ${checks} checks, ${failures} failures`);
if (failures > 0) process.exitCode = 1;

// Design-selected verifier for obligations 2, 7, 8, 10 and 11.
// Reads the verifier files as text only; never imports or executes them or src/hello.mjs.
import fs from "node:fs";
import path from "node:path";
import { fileURLToPath } from "node:url";
import crypto from "node:crypto";

const root = path.resolve(path.dirname(fileURLToPath(import.meta.url)), "..");
let checks = 0;
let failures = 0;

function check(id, reasons) {
  checks += 1;
  if (reasons.length === 0) {
    console.log(`ok ${id}`);
  } else {
    failures += 1;
    console.log(`not ok ${id} - ${reasons.join("; ")}`);
  }
  return reasons.length === 0;
}

function read(rel) {
  try {
    const bytes = fs.readFileSync(path.join(root, rel));
    const digest = crypto.createHash("sha256").update(bytes).digest("hex");
    console.log(`digest ${rel} sha256:${digest}`);
    return { text: bytes.toString("utf8"), digest };
  } catch {
    return null;
  }
}

const ALLOWED_SPECIFIERS = new Set(["node:test", "node:assert/strict", "../../src/hello.mjs"]);
const SUITES = [
  { suite: "component", rel: "test/component/hello.test.mjs", prefix: "component:" },
  { suite: "uat", rel: "test/uat/hello.uat.test.mjs", prefix: "uat:" },
];

const singleTest = {};
const testCounts = {};
const digests = {};

for (const { suite, rel, prefix } of SUITES) {
  const file = read(rel);
  const text = file ? file.text : null;
  const absent = [`${rel} missing or unreadable`];
  const has = (needle) => (text !== null && text.includes(needle) ? [] : text === null ? absent : [`lacks '${needle}'`]);
  digests[suite] = file ? file.digest : null;

  check(`${suite}-node-test`, has('import { test } from "node:test"'));
  check(`${suite}-assert-strict`, has('import assert from "node:assert/strict"'));
  check(`${suite}-exact-import`, has('import { helloWorld } from "../../src/hello.mjs"'));

  {
    const reasons = [];
    if (text === null) {
      reasons.push(...absent);
    } else {
      const specifiers = [
        ...[...text.matchAll(/from\s+["']([^"']+)["']/g)].map((m) => m[1]),
        ...[...text.matchAll(/import\(\s*["']([^"']+)["']/g)].map((m) => m[1]),
      ];
      for (const specifier of specifiers) {
        if (!ALLOWED_SPECIFIERS.has(specifier)) reasons.push(`unexpected specifier ${specifier}`);
      }
    }
    check(`${suite}-import-set`, reasons);
  }

  {
    const resolved = path.resolve(path.dirname(path.join(root, rel)), "../../src/hello.mjs");
    const subject = path.join(root, "src/hello.mjs");
    const reasons = [];
    if (resolved !== subject) reasons.push(`specifier resolves to ${resolved}`);
    if (!fs.existsSync(subject)) reasons.push("src/hello.mjs missing");
    check(`${suite}-resolves-to-subject`, reasons);
  }

  check(`${suite}-strict-assertion`, has('assert.strictEqual(helloWorld(), "Hello, world!")'));
  check(`${suite}-name-prefix`, has(`test("${prefix}`));

  {
    const count = text === null ? 0 : (text.match(/\btest\(/g) || []).length;
    testCounts[suite] = count;
    singleTest[suite] = check(`${suite}-single-test`, text === null ? absent : count === 1 ? [] : [`test( occurs ${count} times`]);
  }

  {
    const reasons = [];
    if (text === null) reasons.push(...absent);
    else {
      if (text.includes("describe(")) reasons.push("contains describe(");
      if (text.includes("suite(")) reasons.push("contains suite(");
      if (/\bit\(/.test(text)) reasons.push("contains it(");
    }
    check(`${suite}-no-other-test-forms`, reasons);
  }

  {
    const reasons = [];
    if (text === null) reasons.push(...absent);
    else {
      const lower = text.toLowerCase();
      for (const token of ["skip", "todo", ".only"]) {
        if (lower.includes(token)) reasons.push(`contains ${token}`);
      }
    }
    check(`${suite}-no-skip-or-focus`, reasons);
  }

  {
    const reasons = [];
    if (text === null) reasons.push(...absent);
    else {
      for (const token of ["console.", "process.", "stdout", "child_process", "mock"]) {
        if (text.includes(token)) reasons.push(`contains ${token}`);
      }
    }
    check(`${suite}-no-doubles-or-output`, reasons);
  }
}

{
  const reasons = [];
  if (!digests.component || !digests.uat) reasons.push("a verifier file is missing");
  else if (digests.component === digests.uat) reasons.push("verifier files are identical");
  check("verifiers-distinct", reasons);
}

{
  const total = (testCounts.component || 0) + (testCounts.uat || 0);
  check("verifiers-total-tests", total === 2 ? [] : [`test( occurs ${total} times across both files`]);
}

// Static basis of rule D-suite; not an observation of any run.
if (singleTest.component && singleTest.uat) {
  console.log("note suite-attribution-basis component=1 uat=1");
}

console.log(`check-verifier-structure: ${checks} checks, ${failures} failures`);
if (failures > 0) process.exitCode = 1;

// Design-selected verifier for obligations 9, 10, 11 and 14.
// Read-only: never imports or executes subject code, spawns nothing, writes nothing.
import fs from "node:fs";
import path from "node:path";
import { fileURLToPath } from "node:url";
import crypto from "node:crypto";

const root = path.resolve(path.dirname(fileURLToPath(import.meta.url)), "..");
let checks = 0;
let failures = 0;

// The design's literal planned-verifier-run arguments.
const PLANNED_ARGS = ["--test", "test/component/hello.test.mjs", "test/uat/hello.uat.test.mjs"];
// The literal of the planned-run-pass-floor predicate.
const PASS_FLOOR_LITERAL = 2;
// The source's expectedReturnValue.
const EXPECTED_RETURN_VALUE = "Hello, world!";
const VERIFIERS = ["test/component/hello.test.mjs", "test/uat/hello.uat.test.mjs"];
const OBSERVED_RESULT_KEYS = ["executionStatus", "planSatisfied", "observedTestPassCount", "stdoutDigest", "observedReturnValue", "result", "results"];

function check(id, reasons) {
  checks += 1;
  if (reasons.length === 0) {
    console.log(`ok ${id}`);
  } else {
    failures += 1;
    console.log(`not ok ${id} - ${reasons.join("; ")}`);
  }
}

function read(rel) {
  try {
    const bytes = fs.readFileSync(path.join(root, rel));
    console.log(`digest ${rel} sha256:${crypto.createHash("sha256").update(bytes).digest("hex")}`);
    return bytes.toString("utf8");
  } catch {
    return null;
  }
}

const planText = read("test-execution-plan.json");
const verifierTexts = VERIFIERS.map((rel) => read(rel));

let plan = null;
let parseReason = null;
if (planText === null) {
  parseReason = "test-execution-plan.json missing or unreadable";
} else {
  try {
    plan = JSON.parse(planText);
    if (plan === null || typeof plan !== "object" || Array.isArray(plan)) {
      parseReason = "plan is not a JSON object";
      plan = null;
    }
  } catch (error) {
    parseReason = `plan does not parse: ${error.message}`;
  }
}

function planCheck(id, evaluate) {
  check(id, plan === null ? [parseReason] : evaluate(plan));
}

check("plan-parses", parseReason ? [parseReason] : []);
planCheck("plan-command", (p) => (p.command === "node" ? [] : [`command is ${JSON.stringify(p.command)}`]));
planCheck("plan-args", (p) => (JSON.stringify(p.args) === JSON.stringify(PLANNED_ARGS) ? [] : [`args are ${JSON.stringify(p.args)}`]));
planCheck("plan-args-exist", (p) => {
  if (!Array.isArray(p.args)) return ["args is not an array"];
  const listed = p.args.filter((a) => typeof a === "string" && !a.startsWith("--"));
  if (listed.length !== 2) return [`args list ${listed.length} files`];
  return listed.filter((rel) => !fs.existsSync(path.join(root, rel))).map((rel) => `${rel} does not exist`);
});
planCheck("plan-pass-floor", (p) =>
  Number.isInteger(p.expectedTestPassCount) && p.expectedTestPassCount >= 2 ? [] : [`expectedTestPassCount is ${JSON.stringify(p.expectedTestPassCount)}`],
);
planCheck("plan-pass-floor-achievable", (p) => {
  if (verifierTexts.some((t) => t === null)) return ["a verifier file is missing"];
  const declared = verifierTexts.reduce((sum, t) => sum + (t.match(/\btest\(/g) || []).length, 0);
  return typeof p.expectedTestPassCount === "number" && p.expectedTestPassCount <= declared
    ? []
    : [`expectedTestPassCount ${JSON.stringify(p.expectedTestPassCount)} exceeds ${declared} declared tests`];
});
planCheck("plan-pass-floor-matches-predicate", (p) =>
  p.expectedTestPassCount === PASS_FLOOR_LITERAL ? [] : [`expectedTestPassCount ${JSON.stringify(p.expectedTestPassCount)} differs from predicate literal ${PASS_FLOOR_LITERAL}`],
);
planCheck("plan-stdout-match", (p) =>
  typeof p.expectedStdoutMatch === "string" && p.expectedStdoutMatch.includes("fail 0") ? [] : [`expectedStdoutMatch is ${JSON.stringify(p.expectedStdoutMatch)}`],
);
planCheck("plan-no-pass-pin", (p) =>
  typeof p.expectedStdoutMatch === "string" && /pass\s*\d/i.test(p.expectedStdoutMatch) ? ["expectedStdoutMatch pins a pass count"] : [],
);
planCheck("plan-asserted-return-value", (p) =>
  p.assertedReturnValue === EXPECTED_RETURN_VALUE ? [] : [`assertedReturnValue is ${JSON.stringify(p.assertedReturnValue)}`],
);
planCheck("plan-no-observed-result", (p) => OBSERVED_RESULT_KEYS.filter((k) => Object.hasOwn(p, k)).map((k) => `contains ${k}`));

console.log(`check-plan: ${checks} checks, ${failures} failures`);
if (failures > 0) process.exitCode = 1;

// Design-selected verifier for obligations 5, 6, 9 and 12.
// Checks named derivation edges and cross-surface facts. It cannot observe the
// admitted construction basis or write order; those are reported as notes.
// Read-only: never imports or executes subject code, spawns nothing, writes nothing.
import fs from "node:fs";
import path from "node:path";
import { fileURLToPath } from "node:url";
import crypto from "node:crypto";

const root = path.resolve(path.dirname(fileURLToPath(import.meta.url)), "..");
let checks = 0;
let failures = 0;

const CONFORMANCE = "specification/project-conformance.md";
const IMPLEMENTATION = "design/implementation-design.md";
const PACKAGE = "package.json";
const SOURCE = "src/hello.mjs";
const TEST_DESIGN = "design/test-design.md";
const COMPONENT = "test/component/hello.test.mjs";
const UAT = "test/uat/hello.uat.test.mjs";
const PLAN = "test-execution-plan.json";
const SURFACES = [CONFORMANCE, IMPLEMENTATION, PACKAGE, SOURCE, TEST_DESIGN, COMPONENT, UAT, PLAN];

function check(id, reasons) {
  checks += 1;
  if (reasons.length === 0) {
    console.log(`ok ${id}`);
  } else {
    failures += 1;
    console.log(`not ok ${id} - ${reasons.join("; ")}`);
  }
}

const bytes = {};
const texts = {};
for (const rel of SURFACES) {
  try {
    bytes[rel] = fs.readFileSync(path.join(root, rel));
    texts[rel] = bytes[rel].toString("utf8");
  } catch {
    bytes[rel] = null;
    texts[rel] = null;
  }
}

function parse(rel) {
  if (texts[rel] === null) return null;
  try {
    return JSON.parse(texts[rel]);
  } catch {
    return null;
  }
}
const pkg = parse(PACKAGE);
const plan = parse(PLAN);

function contains(rel, needles) {
  if (texts[rel] === null) return [`${rel} missing or unreadable`];
  return needles.filter((n) => !texts[rel].includes(n)).map((n) => `${rel} lacks '${n}'`);
}

const EDGES = [
  ["edge-conformance-design", () => [
    ...contains(IMPLEMENTATION, ["Authority: specification/project-conformance.md"]),
    ...contains(CONFORMANCE, ["design/implementation-design.md"]),
  ]],
  ["edge-design-source", () => [
    ...contains(SOURCE, ["design/implementation-design.md"]),
    ...contains(IMPLEMENTATION, ["private", "module"]),
    ...(pkg === null ? [`${PACKAGE} missing or unparsable`] : []),
    ...(pkg !== null && pkg.private !== true ? ["package.json private is not true"] : []),
    ...(pkg !== null && pkg.type !== "module" ? ["package.json type is not module"] : []),
  ]],
  ["edge-source-test-design", () => contains(TEST_DESIGN, ["Evidence source: package.json and src/hello.mjs"])],
  ["edge-test-design-component", () => contains(COMPONENT, ["design/test-design.md", "src/hello.mjs"])],
  ["edge-to-uat", () => contains(UAT, ["test/component/hello.test.mjs", "design/test-design.md", "src/hello.mjs"])],
  ["edge-verifiers-plan", () => {
    if (plan === null) return [`${PLAN} missing or unparsable`];
    const reasons = [];
    const expected = JSON.stringify([COMPONENT, UAT]);
    if (JSON.stringify(plan.derivedFrom) !== expected) reasons.push(`derivedFrom is ${JSON.stringify(plan.derivedFrom)}`);
    if (!Array.isArray(plan.args) || JSON.stringify(plan.derivedFrom) !== JSON.stringify(plan.args.slice(1))) {
      reasons.push("derivedFrom does not equal args.slice(1)");
    }
    return reasons;
  }],
];

for (const [id, evaluate] of EDGES) check(id, evaluate());

const FACT_FILES = [IMPLEMENTATION, TEST_DESIGN, SOURCE, COMPONENT, UAT];
check("fact-function-name", FACT_FILES.flatMap((rel) => contains(rel, ["helloWorld"])));
check("fact-return-value", [
  ...FACT_FILES.flatMap((rel) => contains(rel, ["Hello, world!"])),
  ...(plan === null ? [`${PLAN} missing or unparsable`] : plan.assertedReturnValue === "Hello, world!" ? [] : ["assertedReturnValue differs"]),
]);
check("fact-module-path", [IMPLEMENTATION, TEST_DESIGN].flatMap((rel) => contains(rel, ["src/hello.mjs"])));
check("fact-verifier-paths", [
  ...[IMPLEMENTATION, TEST_DESIGN].flatMap((rel) => contains(rel, [COMPONENT, UAT])),
  ...(plan === null || !Array.isArray(plan.args)
    ? [`${PLAN} args unavailable`]
    : [COMPONENT, UAT].filter((rel) => !plan.args.includes(rel)).map((rel) => `plan args lack ${rel}`)),
]);

for (const rel of SURFACES) {
  if (bytes[rel] === null) console.log(`digest ${rel} missing`);
  else console.log(`digest ${rel} sha256:${crypto.createHash("sha256").update(bytes[rel]).digest("hex")}`);
}
for (const [id] of EDGES) console.log(`note construction-basis-not-admitted ${id}`);
console.log("note derivation-order-not-observable");

console.log(`check-derivation: ${checks} checks, ${failures} failures`);
if (failures > 0) process.exitCode = 1;

criteria.explanation:
I compared every statement with the full source, the admitted predecessor assets (Requirements 7a978d3c, Design 8bbebc05), and the admitted artifact bodies and command record.

These facts match the evidence:
- the digests and byte lengths of all eight subject surfaces;
- the nine command-observation refs, with their stdout digests and empty stderr;
- the 13 predicate observations;
- snapshot 4c4a716c and its source-observation refs;
- the verbatim stdout, and the checker totals and notes;
- the construction provenance (b28cfddc, admitted, advance) and the empty deltas;
- the revision cause (0cc86f61, no selected obligations).

The mapping to the source's judged fields is faithful: executionStatus is the exit status, observedTestPassCount is 2, the stdout digest is 6f9ba47c, and planSatisfied is correctly reported as not computed. My own reading of the bodies (judgment, not admission) agrees that every source-required element is present and scope is not widened.

Two minor defects:
(1) Statement 07 gives check-inventory.mjs as sha256:327d0fdb5a67..., which is 63 hex characters. The admitted digest is 327d0fdbc5a67ddf...c2a517; the 'c' was dropped.
(2) Statement 15 says condition 1 'holds by computation', but its own pressure 05 correctly says no admitted verdict is recorded.

Each of the 15 active obligations has its own statement (04 to 18). Each statement keeps realization, verifier artifact, verifier execution and semantic assessment distinct. For obligations 7 and 8 the verifier files are the realization, and check-verifier-structure is their separate execution.

I checked every binding's required content. Each item is either present with admitted refs or named as a gap:
- obligation 10 derivation output: G1/G2;
- obligation 11 per-condition evaluator record: pressure 05;
- digest-basis content for obligations 5, 6, 9 and 12: G3;
- same-run per-suite attribution: G2;
- the stdout-fragment comparison: G1.

The candidate closes nothing on a count, an exit status or a name. Pass counts are never used to infer suite passes. No requirement or binding is added, and design is null.

The asset binds evidence and reports gaps only. It separates three things:
- construction readiness: all 14 targets were written;
- observed behavior, limited to the one recorded run;
- the remaining obligations: G1, G2, G3, readiness classification, assessment and the owner's acceptance.

It closes nothing and infers no acceptance or release. Statement 01 correctly says the records do not show current physical state.

One minor point: statement 24 says the targets 'exist' in the present tense. It should say they existed at the recorded execution.
